<?php
session_start(); require 'db.php';
if (!isset($_SESSION['role']) || $_SESSION['role'] !== 'faculty') { header('Location: index.php'); exit(); }
$schedule_id=(int)($_GET['schedule_id']??0); $faculty_id=(int)($_SESSION['user_id']??0); $name=$_SESSION['name']??'';
$conn->query("CREATE TABLE IF NOT EXISTS student_subjects (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, schedule_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_enrollment (student_id,schedule_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$stmt=$conn->prepare("SELECT s.* FROM schedules s WHERE s.id=? AND (s.faculty_id=? OR (s.faculty_id IS NULL AND s.faculty=?)) LIMIT 1"); $stmt->bind_param('iis',$schedule_id,$faculty_id,$name); $stmt->execute(); $schedule=$stmt->get_result()->fetch_assoc(); if(!$schedule){http_response_code(404);exit('Schedule not found or not assigned to you.');}
$stmt=$conn->prepare("SELECT u.student_id,u.full_name,u.course,u.year_level FROM student_subjects ss JOIN users u ON u.id=ss.student_id WHERE ss.schedule_id=? AND u.role='student' AND u.status='Registered' ORDER BY u.course,u.year_level,u.full_name"); $stmt->bind_param('i',$schedule_id); $stmt->execute(); $students=$stmt->get_result();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masterlist - SAMS</title><link rel="stylesheet" href="faculty.css?v=3"></head><body><div class="header"><div class="header-title"><h2>ACLC College of Malolos - SAMS</h2><span>Subject masterlist</span></div><div class="header-user"><a href="faculty.php">Dashboard</a><a href="logout.php">Logout</a></div></div><main class="container"><h1><?php echo htmlspecialchars($schedule['subject']); ?></h1><p class="subtitle"><?php echo htmlspecialchars($schedule['course'].' '.$schedule['section'].' • '.$schedule['schedule_date']); ?></p><div class="table-wrap"><table><thead><tr><th>#</th><th>Student ID</th><th>Student Name</th><th>Course</th><th>Year Level</th></tr></thead><tbody><?php $n=1; while($student=$students->fetch_assoc()): ?><tr><td><?php echo $n++; ?></td><td><?php echo htmlspecialchars($student['student_id']?:'—'); ?></td><td><?php echo htmlspecialchars($student['full_name']); ?></td><td><?php echo htmlspecialchars($student['course']); ?></td><td><?php echo htmlspecialchars($student['year_level']); ?></td></tr><?php endwhile; ?></tbody></table></div></main></body></html>
